const orders = [{total:120,status:'paid'},{total:80,status:'pending'},{total:200,status:'paid'}];
const paid = orders.filter(o => o.status === 'paid');
const totals = paid.map(o => o.total);
const revenue = totals.reduce((sum, n) => sum + n, 0);
console.log(revenue);

const firstLarge = orders.find(o => o.total >= 150);
const hasPending = orders.some(o => o.status === 'pending');
const allValid = orders.every(o => o.total > 0);
console.log(firstLarge, hasPending, allValid);
